assert s.count(line)==1
helper='''
static void ExportVerified(object value,string output){
 var payload=JsonSerializer.SerializeToUtf8Bytes(value);
 string hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(payload)).ToLowerInvariant();
 string backup=output+".raw.json",tmp=backup+".tmp";
 using(var f=new FileStream(tmp,FileMode.Create,FileAccess.Write,FileShare.None)){f.Write(payload);f.Flush(true);}File.Move(tmp,backup,true);
 for(int attempt=0;attempt<3;attempt++){
  string candidate=output+".tmp";
  using(var f=new FileStream(candidate,FileMode.Create,FileAccess.Write,FileShare.None)){
   using(var gz=new System.IO.Compression.GZipStream(f,System.IO.Compression.CompressionLevel.Fastest,true)){gz.Write(payload);}f.Flush(true);
  }
  string actual;using(var f=File.OpenRead(candidate))using(var gz=new System.IO.Compression.GZipStream(f,System.IO.Compression.CompressionMode.Decompress))actual=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(gz)).ToLowerInvariant();
  if(actual!=hash){if(attempt==2)throw new IOException("EXPORT_HASH_MISMATCH");continue;}
  File.Move(candidate,output,true);File.WriteAllText(output+".integrity.json",JsonSerializer.Serialize(new{Verified=true,UncompressedSha256=hash,UncompressedBytes=payload.Length}));return;
 }throw new IOException("EXPORT_FAILED");
}
'''
s=s.replace(line,' ExportVerified(result,output);');s=s.replace('record struct Row',helper+'\nrecord struct Row')
needle='var requested=args.Length>3?args[3]:"smoke";';assert needle in s;s=s.replace(needle,'if(args.Length>3&&args[3]=="tapes-only"){Console.WriteLine("TAPES_ONLY_COMPLETE");return;}\n'+needle)
assert s.replace(helper+'\n','').replace(' ExportVerified(result,output);',line).replace('if(args.Length>3&&args[3]=="tapes-only"){Console.WriteLine("TAPES_ONLY_COMPLETE");return;}\n','')==original
p.write_text(s)
for old in (S/'source').rglob('*.cs'):assert old.read_bytes()==(T/'source'/old.relative_to(S/'source')).read_bytes()
files=list((T/'source').rglob('*.cs'))+[T/'tests/Global.cs',T/'replay/ApiStubs.cs',T/'replay/ResearchAccounting.cs',p]
runtime=W/'dotnet/shared/Microsoft.NETCore.App/8.0.32';args=['-nologo','-target:exe','-langversion:latest','-nullable:enable','-define:REPLAY','-out:'+str(T/'replay/Replay.dll')]+['-r:'+str(p) for p in runtime.glob('*.dll')]+[str(p) for p in files]
(T/'replay/build.rsp').write_text('\n'.join(args))
with (T/'replay/compile.log').open('w') as f:subprocess.run([str(W/'dotnet_host/dotnet'),str(W/'diagnostics/compiler/tasks/netcore/bincore/csc.dll'),'@'+str(T/'replay/build.rsp')],stdout=f,stderr=f,check=True)
proof={'replay_only':True,'original_dll_sha256':hashlib.sha256((S/'replay/Replay.dll').read_bytes()).hexdigest(),'new_dll_sha256':hashlib.sha256((T/'replay/Replay.dll').read_bytes()).hexdigest(),'strategy_sources_identical':True,'economic_runner_identical_except_export_and_tapes_only_mode':True,'source_hashes':{str(p.relative_to(T)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files},'required_control':'2019 Bcost2 full raw JSON sha must match frozenR3'}
(R/'BUILD.json').write_text(json.dumps(proof,indent=2));print(json.dumps({k:v for k,v in proof.items() if k!='source_hashes'},indent=2))

