from pathlib import Path
import os,json,hashlib,subprocess,time,threading,concurrent.futures,gzip,shutil,fcntl
R=Path(__file__).resolve().parent;W=R.parent;BIN=R/'engine/replay/Replay.dll';HOST=W/'dotnet_host/dotnet';INPUT=W/'v4_resume/inputs'
profile=json.loads((R/'R3_I100_W060.json').read_text());lock=json.loads((R/'FROZEN_R3_LOCK.json').read_text());build=json.loads((R/'BUILD.json').read_text());assert hashlib.sha256(BIN.read_bytes()).hexdigest()==build['new_dll_sha256']
write_lock=threading.Lock();loaded=threading.Event();jobs={}
def put(p,obj):
 p.parent.mkdir(parents=True,exist_ok=True);t=p.with_suffix(p.suffix+'.tmp');t.write_text(json.dumps(obj,indent=2)+'\n');t.replace(p)
def status(stage,**kw):put(R/'STATUS.json',dict(stage=stage,updated_utc=time.time(),**kw))
def link(folder,name,target):
 p=folder/name
 if not p.exists():p.symlink_to(target)
control=R/'control_2019';extended=R/'extended';control.mkdir(exist_ok=True);extended.mkdir(exist_ok=True)
for name in ['fresh_xau_tape.json','fresh_eur_tape.json']:link(control,name,W/'buffer_growth'/name)
link(extended,'fresh_eur_tape.json',W/'buffer_growth/fresh_eur_tape.json')

def _run(folder,year,cost,path,btc,cache=None,mode='full',on_loaded=None):
 folder.mkdir(parents=True,exist_ok=True);config=folder/'profile.json';put(config,profile)
 name=folder.name;jobpath=folder/'JOB.json';complete=folder/'COMPLETE.json'
 if complete.exists():
  old=json.loads(complete.read_text())
  if old.get('success') and old.get('binary_sha256')==build['new_dll_sha256']:
   for file,sha in old.get('outputs',{}).items():assert hashlib.sha256(Path(file).read_bytes()).hexdigest()==sha
   print('REUSE',name,flush=True)
   if on_loaded:on_loaded.set()
   return
 env={k:v for k,v in os.environ.items() if not k.startswith(('RESEARCH_','BTC_'))}
 env.update(BTC_INPUT=str(btc),RESEARCH_CONFIGS=str(config),RESEARCH_PATH=path,RESEARCH_COST=str(cost),DOTNET_GCHeapHardLimit=('0x180000000' if mode=='tapes-only' else '0xC0000000'),DOTNET_gcServer='1',DOTNET_GCHeapCount='4')
 if cache:env['BTC_SIGNAL_CACHE']=str(cache)
 cmd=[str(HOST),str(BIN),str(INPUT/'xau_2012_2026.csv'),str(INPUT/'eur_2012_2026.csv'),str(folder/'RUN.json'),mode,str(year),'2026']
 info={'started_utc':time.time(),'cmd':cmd,'binary_sha256':build['new_dll_sha256'],'start_year':year,'cost':cost,'path':path,'BTC_input':str(btc),'BTC_cache':str(cache) if cache else None,'profile':profile,'real_orders':0}
 with (folder/'replay.log').open('w') as log:
  p=subprocess.Popen(cmd,stdout=log,stderr=log,env=env);info['pid']=p.pid;put(jobpath,info)
  print('START',name,p.pid,flush=True);last=''
  while p.poll() is None:
   time.sleep(10);lines=(folder/'replay.log').read_text(errors='replace').splitlines()
   if on_loaded and any(v.startswith('TAPES ') for v in lines):on_loaded.set()
   if lines and last!=lines[-1]:last=lines[-1];print(name,last[:450],flush=True)
  info.update(returncode=p.returncode,finished_utc=time.time());put(jobpath,info)
 if on_loaded:on_loaded.set()
 if p.returncode:raise RuntimeError(name+' replay failed '+str(p.returncode))
 outputs={}
 if mode=='full':
  for way in path:
   f=folder/f'R3_I100_W060_{way}_cost{cost}.json.gz'
   with gzip.open(f,'rb') as z:payload=z.read()
   data=json.loads(payload);proof=json.loads(Path(str(f)+'.integrity.json').read_text());assert proof['Verified'] and hashlib.sha256(payload).hexdigest()==proof['UncompressedSha256']
   outputs[str(f)]=hashlib.sha256(f.read_bytes()).hexdigest()
 put(complete,dict(success=True,binary_sha256=build['new_dll_sha256'],outputs=outputs));print('END',name,flush=True)

def run(folder,*args,**kw):
 folder.mkdir(parents=True,exist_ok=True)
 with (folder/'JOB.lock').open('a') as guard:
  fcntl.flock(guard,fcntl.LOCK_EX)
  return _run(folder,*args,**kw)

def main():
 status('building_2016_tape_and_verifying_2019_control',complete=False)
 with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
  future=pool.submit(run,control/'B_COST2',2019,2,'B',INPUT/'BTCUSD_M1.csv',W/'v4_resume/baseline/results/FROZEN_7D130_A.json.btc_signals.json','full',loaded)
  while not loaded.wait(10):
   if future.done():future.result()
  run(extended/'TAPES_HEAP6G',2016,1,'A',R/'data/BTCUSD_2016_2026_M1.csv',mode='tapes-only')
  future.result()
 # A full raw JSON hash compares every field to the frozen report, no exclusions.
 ref=next(x for x in lock['raw_lineage'] if x['original_path']=='SCREEN_B_C2/R3_I100_W060_B_cost2.json.gz')
 raw=control/'B_COST2/R3_I100_W060_B_cost2.json.gz.raw.json';actual=hashlib.sha256(raw.read_bytes()).hexdigest();assert actual==ref['JSON_sha256'],('CONTROL_FULL_RAW_HASH_MISMATCH',actual,ref['JSON_sha256'])
 old=json.loads((W/'buffer_growth/fresh_xau_tape.json').read_text());new=json.loads((extended/'fresh_xau_tape.json').read_text());old_signals=old['Signals'];comparable=[v for v in new['Signals'] if v['At']>='2019'];assert comparable==old_signals,'XAU_2019_PLUS_SIGNAL_PARITY';assert new['Confirmations']==old['Confirmations'],'XAU_CONFIRMATION_PARITY'
 pre={str(y):sum(v['At'].startswith(str(y)) for v in new['Signals']) for y in [2016,2017,2018]};assert all(v>0 for v in pre.values())
 proof={'pass':True,'control_2019_full_raw_sha256':actual,'frozen_raw_sha256':ref['JSON_sha256'],'full_raw_no_excluded_fields':True,'XAU_2019_plus_exact_signal_parity':True,'XAU_confirmations_identical':True,'new_XAU_raw_signal_counts':pre,'frozen_strategy_parameters_unchanged':True,'LIVE_unchanged':True}
 put(R/'CONTROL_PARITY.json',proof);print('CONTROL_AND_2016_TAPE_PARITY_PASS',flush=True)
 btc_cache=extended/'TAPES_HEAP6G/RUN.json.btc_signals.json'
 status('six_2016_scenarios_running',complete=False,control_pass=True)
 with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
  tasks=[pool.submit(run,extended/('COST'+str(cost)),2016,cost,'AB',R/'data/BTCUSD_2016_2026_M1.csv',btc_cache) for cost in [2,1,1.5]]
  for task in tasks:task.result()
 status('six_replays_complete_ready_for_audit',complete=False,control_pass=True)
 print('SIX_COMPLETE_AUDIT_NEXT',flush=True)
if __name__=='__main__':
 try:main()
 except BaseException as e:status('error',complete=False,error=repr(e));raise

